1. using System.ComponentModel;
2. using ModelContextProtocol.Server;
3. using Microsoft.Extensions.Logging;
4. 
5. namespace McpServer.Tools;
6. 
7. [McpServerToolType]
8. public sealed class FetchDataTool
9. {
10.     [McpServerTool, Description("Fetches data from an external API endpoint.")]
11.     public static async Task<string> FetchData(
12.         HttpClient httpClient,
13.         ILogger<FetchDataTool> logger,
14.         [Description("The API endpoint path to fetch (e.g. \"users/1\")")] string endpoint,
15.         CancellationToken cancellationToken = default)
16.     {
17.         logger.LogInformation("Fetching data from endpoint: {Endpoint}", endpoint);
18. 
19.         var response = await httpClient.GetAsync(endpoint, cancellationToken);
20.         response.EnsureSuccessStatusCode();
21. 
22.         var content = await response.Content.ReadAsStringAsync(cancellationToken);
23.         logger.LogInformation("Successfully fetched {Length} characters", content.Length);
24. 
25.         return content;
26.     }
27. }
28.

